          <div class="operator-trend"><div class="panel-header"><div><p class="eyebrow">Vergelijken door de tijd</p><h2>Dagtrend per rederij</h2></div><select v-model="trendMetric" aria-label="Trendmeting"><option value="distanceKm">Kilometers</option><option value="movingHours">Vaaruren</option><option value="activeBoats">Actieve boten</option></select></div>
