        </section>
        <section v-if="activeTab==='waterways'" class="view-panel"><section class="panel"><div class="panel-header"><div><p class="eyebrow">Ruimtelijk overzicht</p><h2>Waar is de vloot actief?</h2></div><select v-model="mapMetric" aria-label="Kaartmeting"><option value="activeBoats">Unieke varende boten</option><option value="movingHours">Vaaruren</option><option value="stoppedHours">Stilstanduren</option></select></div><FleetDensityMap :cells="report.density" :metric="mapMetric" /></section><section class="panel"><div class="panel-header"><div><p class="eyebrow">Benadering via vaarwegnetwerk</p><h2>Gebruikte grachten en vaarwegen</h2></div></div><p class="caption">Bewegende meetintervallen worden gekoppeld aan de dichtstbijzijnde vaarweg binnen 40 meter. Op kruisingen en bij schaarse ontvangst kan de naamtoekenning afwijken.</p><div class="table-scroll"><table><thead><tr><th>Vaarweg</th><th>Unieke varende boten</th><th>Geschatte km</th><th>Gemeten vaaruren</th></tr></thead><tbody><tr v-for="way in report.waterways" :key="way.name"><th>{{ way.name }}</th><td>{{ way.activeBoats }}</td><td>{{ number(way.distanceKm) }}</td><td>{{ number(way.movingHours) }}</td></tr></tbody></table></div><p v-if="!report.waterways.length" class="empty-state">Geen bewegende intervallen aan een vaarweg gekoppeld.</p></section></section>
        <section v-if="activeTab==='stops'" class="view-panel"><section class="method-note"><strong>Stilstand is geen bewezen wachttijd of steigerbezoek.</strong> Hier staan ontvangen stilstandintervallen van minimaal drie minuten, binnen ongeveer 35 meter. Een bezoeker, ligplaats of ontbrekend ontvangstsignaal is geen bevestigde passagiersvaart. Brug- en sluisverblijf wordt binnen een straal van 45 meter gemeten.</section><section class="panel"><div class="panel-header"><div><p class="eyebrow">Bruggen en sluizen</p><h2>Gemeten verblijf nabij meetlocaties</h2></div></div><div class="table-scroll"><table><thead><tr><th>Locatie</th><th>Type</th><th>Stilstandbezoeken</th><th>Boten</th><th>Totaal minuten</th><th>Gemiddeld minuten</th></tr></thead><tbody><tr v-for="location in report.locations" :key="location.id"><th>{{ location.name }}</th><td>{{ location.type }}</td><td>{{ location.visits }}</td><td>{{ location.boats }}</td><td>{{ number(location.observedMinutes,1) }}</td><td>{{ number(location.meanMinutes,1) }}</td></tr></tbody></table></div><p v-if="!report.locations.length" class="empty-state">Geen geografische meetlocaties beschikbaar.</p></section><section class="panel"><div class="panel-header"><div><p class="eyebrow">Mogelijke lig- en opstapplaatsen</p><h2>Meest waargenomen stopgebieden</h2></div></div><p class="caption">Geclusterde stopposities; geen officieel steigerregister. De vaarwegnaam is een ruimtelijke benadering.</p><div class="table-scroll"><table><thead><tr><th>Gebied / vaarweg</th><th>Positie</th><th>Bezoeken</th><th>Boten</th><th>Minuten</th><th>Gemiddeld</th></tr></thead><tbody><tr v-for="(stop,index) in report.stops" :key="index"><th>{{ stop.waterway || 'Naam onbekend' }}</th><td>{{ stop.latitude.toFixed(4) }}, {{ stop.longitude.toFixed(4) }}</td><td>{{ stop.visits }}</td><td>{{ stop.boats }}</td><td>{{ number(stop.observedMinutes,1) }}</td><td>{{ number(stop.meanMinutes,1) }}</td></tr></tbody></table></div><p v-if="!report.stops.length" class="empty-state">Geen voldoende aaneengesloten stilstand gemeten.</p></section></section>
        <section v-if="activeTab==='boats'" class="view-panel"><section class="panel"><div class="panel-header"><div><p class="eyebrow">Van naam naar meting</p><h2>Bootstatistieken</h2></div><input v-model="boatSearch" class="search-input" type="search" placeholder="Zoek boot of MMSI" aria-label="Zoek bootstatistieken" @input="boatPage=1" /></div><div class="table-scroll"><table><thead><tr><th>Boot / rederij</th><th><button type="button" @click="boatSort='distanceKm'">Kilometers ↓</button></th><th><button type="button" @click="boatSort='movingHours'">Vaaruren ↓</button></th><th>Gem. / max km/u</th><th>Geziene stilstanduren</th><th>Observatiegraad</th><th>Metingen / gaten</th><th>Laatste meting</th><th></th></tr></thead><tbody><tr v-for="boat in visibleBoats" :key="boat.id"><th><button type="button" class="text-button" :disabled="!boat.mmsi" @click="selectBoat(boat)">{{ boat.name }}</button><small class="table-subtitle">{{ boat.operatorName }} · {{ boat.mmsi || 'Geen MMSI' }}</small></th><td>{{ number(boat.distanceKm) }}</td><td>{{ number(boat.movingHours) }}</td><td>{{ number(boat.averageSpeedKmh,1) }} / {{ number(boat.maxSpeedKmh,1) }}</td><td>{{ number(boat.stoppedHours) }}</td><td>{{ number(boat.observedPercent,1) }}{{ boat.observedPercent!==null?'%':'' }}</td><td>{{ boat.samples }} / {{ boat.gaps }}</td><td>{{ boat.lastAt ? dateTime(boat.lastAt) : 'Geen ontvangst' }}</td><td><a v-if="boat.mmsi" :href="`/?boat=${boat.mmsi}`">Kaart ↗</a></td></tr></tbody></table></div><div class="pagination"><span>{{ filteredBoats.length }} boten · pagina {{ boatPage }} van {{ boatPages }}</span><div><button type="button" :disabled="boatPage===1" @click="boatPage--">Vorige</button><button type="button" :disabled="boatPage>=boatPages" @click="boatPage++">Volgende</button></div></div></section>
          <section class="panel"><div class="panel-header"><div><p class="eyebrow">Bewegingsperioden tussen stops</p><h2>Geschatte vaarten en losse trajecten</h2></div></div><p class="caption">Een geschatte vaart vereist beweging van minimaal 200 meter en vijf minuten, met aan beide kanten minimaal vijf minuten gemeten stilstand. Ontvangstgaten groter dan vijf minuten breken een traject af. Dit zijn geen boekingen of bevestigde rondvaarten. Getoond: {{ report.trips.length }} van {{ report.tripRowsTotal }} herkende trajecten.</p><div class="table-scroll"><table><thead><tr><th>Boot</th><th>Begin</th><th>Einde</th><th>Km</th><th>Vaarminuten</th><th>Begrenzing</th></tr></thead><tbody><tr v-for="(trip,index) in report.trips" :key="index"><th>{{ trip.name }}</th><td>{{ dateTime(trip.from) }}</td><td>{{ dateTime(trip.until) }}</td><td>{{ number(trip.distanceKm) }}</td><td>{{ number(trip.movingMinutes,1) }}</td><td><span class="tag" :class="trip.complete?'complete':'partial'">{{ trip.complete?'Geschatte vaart':'Onvolledig traject' }}</span></td></tr></tbody></table></div><p v-if="!report.trips.length" class="empty-state">Onvoldoende aaneengesloten metingen om trajecten af te bakenen.</p></section>
        </section>
        <section v-if="activeTab==='quality'" class="view-panel"><div class="kpi-grid"><article class="kpi-card"><span>Ontvangen posities</span><strong>{{ number(report.summary.samples,0) }}</strong><p>Binnen de gekozen periode, boten en uren.</p></article><article class="kpi-card"><span>Observatiegraad</span><strong>{{ number(report.quality.intervalCoveragePercent,1) }}<small>%</small></strong><p>Gemeten intervallen gedeeld door de geselecteerde kloktijd × gekoppelde MMSI’s.</p></article><article class="kpi-card"><span>Ontvangstgaten &gt; 5 minuten</span><strong>{{ number(report.quality.gaps,0) }}</strong><p>Deze intervallen tellen niet mee in tijd en afstand.</p></article><article class="kpi-card"><span>Onrealistische sprongen</span><strong>{{ number(report.quality.rejectedSegments,0) }}</strong><p>Segmenten met afgeleide snelheid boven 35 km/u zijn uitgesloten.</p></article></div><section class="panel method-panel"><h2>Wat betekenen deze cijfers?</h2><dl><div><dt>Actief waargenomen</dt><dd>Een boot met een geldig bewegingsinterval. Ontbrekende ontvangst bewijst geen stilstand.</dd></div><div><dt>Afstand en vaaruren</dt><dd>Alleen opeenvolgende geldige posities binnen vijf minuten tellen mee. Afstand gebruikt GPS-afstand en, waar bruikbaar, gemelde AIS-snelheid. Dit blijft een schatting; meetgaten worden niet opgevuld.</dd></div><div><dt>Vlootinzet</dt><dd>Actief waargenomen boten gedeeld door de huidige bekende vloot, inclusief directoryboten zonder AIS. Een onvolledige directory of uitgeschakelde zender beïnvloedt de verhouding.</dd></div><div><dt>Rederijgeschiedenis</dt><dd>{{ report.quality.classification }} Een wisseling van eigenaar in het verleden wordt niet gereconstrueerd.</dd></div><div><dt>Observatiegraad</dt><dd>Deze waarde zegt hoeveel tijd door opeenvolgende meetpunten wordt ondersteund. Lage waarden kunnen komen door ontbrekende dekking, uitgeschakelde zenders of afwezigheid uit het gebied.</dd></div><div><dt>Beschikbare meetgeschiedenis</dt><dd>{{ report.available.earliest ? dateTime(report.available.earliest) : 'Nog geen posities' }} – {{ report.available.latest ? dateTime(report.available.latest) : '—' }}. De server bewaart maximaal 30 dagen ruwe AIS-historie.</dd></div><div><dt>Geografisch bereik</dt><dd>Amsterdam en omgeving: 52,28–52,45° N en 4,72–5,10° E. Vaarwegnamen zijn benaderd met het lokale vaarnetwerk; de kaart toont ontvangen metingen.</dd></div><div><dt>Wat AIS niet vertelt</dt><dd>Geen betrouwbare passagiersaantallen, bezettingsgraad, omzet, boekingen of reden van stilstand. De dashboardcijfers beschrijven waargenomen vaaractiviteit.</dd></div></dl></section></section>
        <footer class="stats-footer"><span>Gebaseerd op ontvangen AIS-posities · schattingen, geen volledige vaartregistratie.</span><button type="button" @click="activeTab='quality'">Definities & datakwaliteit</button></footer>
      </template>
    </div>
  </main>
</template>
<script setup>
import { computed, defineAsyncComponent, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
const FleetDensityMap = defineAsyncComponent(() => import('./FleetDensityMap.vue'))
const localDate = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Amsterdam', year: 'numeric', month: '2-digit', day: '2-digit' })
const today = localDate.format(new Date())
const shift = (date, days) => new Date(Date.parse(`${date}T12:00:00Z`) + days * 86400000).toISOString().slice(0,10)
const initial = new URLSearchParams(window.location.search)
const query = reactive({ from: initial.get('from') || shift(today,-6), to: initial.get('to') || today, operator: initial.get('operator') || 'all', mmsi: initial.get('mmsi') || '', hour: initial.get('hour') || '', includeUnassigned: initial.get('includeUnassigned') === '1' })
const report = ref(null), loading = ref(false), error = ref(''), activeTab = ref('overview'), dailyMetric = ref('distanceKm'), comparisonMetric = ref('distanceKm'), mapMetric = ref('activeBoats'), boatSearch = ref(''), boatPage = ref(1), boatSort = ref('distanceKm')
const trendMetric = ref('distanceKm'), hiddenTrends = ref([])
let controller
const weekdays = ['Ma','Di','Wo','Do','Vr','Za','Zo']
const tabs = [{id:'overview',label:'Overzicht'},{id:'operators',label:'Rederijen'},{id:'time',label:'Dagen & uren'},{id:'waterways',label:'Kaart & vaarwegen'},{id:'stops',label:'Stops & locaties'},{id:'boats',label:'Boten & vaarten'},{id:'quality',label:'Datakwaliteit'}]
const number = (value, digits=2) => value===null || value===undefined ? '—' : new Intl.NumberFormat('nl-NL',{maximumFractionDigits:digits}).format(value)
const date = (value) => new Intl.DateTimeFormat('nl-NL',{day:'numeric',month:'short',year:'numeric',timeZone:'Europe/Amsterdam'}).format(new Date(`${value}T12:00:00Z`))
const shortDate = (value) => new Intl.DateTimeFormat('nl-NL',{day:'numeric',month:'numeric',timeZone:'Europe/Amsterdam'}).format(new Date(`${value}T12:00:00Z`))
const time = (value) => new Intl.DateTimeFormat('nl-NL',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Amsterdam'}).format(new Date(value))
const dateTime = (value) => new Intl.DateTimeFormat('nl-NL',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Europe/Amsterdam'}).format(new Date(value))
const operatorOptions = computed(() => report.value?.options.operators || [])
const boatOptions = computed(() => (report.value?.options.boats || []).filter((boat) => (query.operator==='all' || boat.operatorId===query.operator) && (boat.operatorId!=='unassigned' || query.includeUnassigned || query.operator==='unassigned')).sort((a,b)=>a.name.localeCompare(b.name,'nl')))
const selectedName = computed(() => { const r=report.value; if(r.range.mmsi) return r.options.boats.find(b=>b.mmsi===r.range.mmsi)?.name || r.range.mmsi; return r.range.operator==='all' ? (r.range.includeUnassigned?'Alle rederijen + overige AIS':'Alle rederijen') : r.options.operators.find(o=>o.id===r.range.operator)?.name || r.range.operator })
const summaryCards = computed(() => { const s=report.value.summary; return [
 {label:'Actief waargenomen boten',value:number(s.activeBoats,0),detail:`${s.observedBoats} boten met een ontvangen positie`},
 {label:'Geschatte afstand',value:number(s.distanceKm),unit:'km',detail:'Alleen geldige aaneengesloten meetintervallen'},
 {label:'Gemeten vaartijd',value:number(s.movingHours),unit:'uur',detail:'Opgeteld over de geselecteerde boten'},
 {label:'Gemeten stilstand',value:number(s.stoppedHours),unit:'uur',detail:'Geen veronderstelde stilstand tijdens meetgaten'},
 {label:'Bekende boten',value:number(s.knownBoats,0),detail:`${s.linkedBoats} boten met een gekoppeld MMSI`},
 {label:'Geschatte vaarten',value:s.completedTrips?number(s.completedTrips,0):'—',detail:s.completedTrips?'Beweging met een gemeten stop aan beide kanten':'Geen volledig begrensde vaarten herkend'},
 {label:'Gem. vaartijd',value:number(s.averageTripMinutes,1),unit:s.averageTripMinutes!==null?'min':'',detail:'Van de volledig begrensde geschatte vaarten'},
 {label:'Onvolledige trajecten',value:number(s.partialLegs,0),detail:'Begin, einde of ontvangst onvoldoende bekend'},
] })
const dailyMetricLabel = computed(()=>({distanceKm:'kilometers',movingHours:'vaaruren',activeBoats:'actieve boten'}[dailyMetric.value]))
const dailyBars = computed(()=>{const days=report.value?.daily||[], max=Math.max(1,...days.map(d=>d[dailyMetric.value])), step=745/Math.max(1,days.length);return days.map((d,i)=>({...d,index:i,value:d[dailyMetric.value],x:40+i*step,width:Math.max(2,step*.65),height:d[dailyMetric.value]/max*175}))})
const comparisonRows = computed(()=>[...(report.value?.operators||[])].sort((a,b)=>(b[comparisonMetric.value]||0)-(a[comparisonMetric.value]||0)))
const comparisonMax = computed(()=>Math.max(1,...comparisonRows.value.map(o=>o[comparisonMetric.value]||0)))
const trendSeries = computed(()=>{
 const r=report.value;if(!r)return []
 const series=r.operators.filter(o=>o.observedBoats>0&&!hiddenTrends.value.includes(o.id)).map(o=>({...o,values:r.daily.map(d=>({date:d.date,value:r.operatorDaily.find(row=>row.date===d.date&&row.operatorId===o.id)?.[trendMetric.value]||0}))}))
 const max=Math.max(1,...series.flatMap(s=>s.values.map(v=>v.value)))
 return series.map(s=>{const values=s.values.map((v,i)=>({...v,x:40+i/Math.max(1,s.values.length-1)*740,y:200-v.value/max*175}));return {...s,values,points:values.map(v=>`${v.x},${v.y}`).join(' ')}})
})
function toggleTrend(id){hiddenTrends.value=hiddenTrends.value.includes(id)?hiddenTrends.value.filter(value=>value!==id):[...hiddenTrends.value,id]}
const hourlyMax = computed(()=>Math.max(.1,...(report.value?.hourly||[]).map(h=>h.movingHours)))
const heatMax = computed(()=>Math.max(1,...(report.value?.heatmap||[]).map(c=>c.meanActiveBoats)))
const heatStyle = (cell)=>({background:!cell.days?'#0b1422':`rgba(45,212,191,${.06+cell.meanActiveBoats/heatMax.value*.8})`,color:cell.meanActiveBoats/heatMax.value>.5?'#061722':'#cbd5e1'})
const filteredBoats = computed(()=>{const search=boatSearch.value.toLowerCase();return [...(report.value?.boats||[])].filter(b=>`${b.name} ${b.mmsi||''} ${b.operatorName}`.toLowerCase().includes(search)).sort((a,b)=>(b[boatSort.value]||0)-(a[boatSort.value]||0))})
const boatPages = computed(()=>Math.max(1,Math.ceil(filteredBoats.value.length/30)))
const visibleBoats = computed(()=>filteredBoats.value.slice((boatPage.value-1)*30,boatPage.value*30))
async function loadReport(){
 controller?.abort();controller=new AbortController();const active=controller;loading.value=true;error.value=''
 try{const params=new URLSearchParams({from:query.from,to:query.to,operator:query.operator});if(query.mmsi)params.set('mmsi',query.mmsi);if(query.hour!=='')params.set('hour',query.hour);if(query.includeUnassigned)params.set('includeUnassigned','1');const response=await fetch(`/api/fleet/statistics?${params}`,{signal:active.signal});const data=await response.json();if(!response.ok)throw new Error(data.error||'Statistieken konden niet worden geladen.');if(controller!==active)return;report.value=data;boatPage.value=1;window.history.replaceState(null,'',`${window.location.pathname}?${params}`)}catch(e){if(e.name!=='AbortError')error.value=e.message}finally{if(controller===active)loading.value=false}
}
function quickPeriod(days){query.to=today;query.from=shift(today,1-days);loadReport()}
function selectOperator(id){query.operator=id;query.mmsi='';loadReport()}
function selectBoat(boat){query.operator=boat.operatorId;query.mmsi=boat.mmsi;loadReport()}
function selectHour(hour){query.hour=hour;loadReport()}
function downloadCsv(name,rows){const cell=value=>{let text=typeof value==='number' ? value.toLocaleString('nl-NL',{useGrouping:false,maximumFractionDigits:8}) : String(value??'');if(typeof value==='string'&&/^\s*[=+\-@]/.test(text))text=`'${text}`;return `"${text.replaceAll('"','""')}"`};const blob=new Blob(['\ufeff'+rows.map(row=>row.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCsv(){const r=report.value;downloadCsv(`bootstatistieken-${r.range.fromDate}-${r.range.toDate}.csv`,[['Boot','MMSI','Rederij','Kilometers','Vaaruren','Stilstanduren','Observatiegraad %','Metingen','Gaten','Geschatte vaarten'],...r.boats.map(b=>[b.name,b.mmsi,b.operatorName,b.distanceKm,b.movingHours,b.stoppedHours,b.observedPercent,b.samples,b.gaps,b.completedTrips])])}
function exportOperators(){const r=report.value;downloadCsv(`rederijen-${r.range.fromDate}-${r.range.toDate}.csv`,[['Rederij','Bekende boten','MMSI','Actief','Gezien','Km','Vaaruren','Km per actieve boot','Waargenomen inzet %'],...r.operators.map(o=>[o.name,o.fleetSize,o.linkedBoats,o.activeBoats,o.observedBoats,o.distanceKm,o.movingHours,o.kmPerActiveBoat,o.observedDeploymentPercent])])}
onMounted(loadReport)
onBeforeUnmount(()=>controller?.abort())
</script>
